/* This case covers control and data frames that carry no payload at all.

   An empty frame is two bytes on the wire, so trimming its header consumes the
   whole packet and _nx_websocket_client_packet_trim() reports NX_NO_PACKET with
   the packet pointer set to NX_NULL.  Every arm of the frame switch in
   _nx_websocket_client_data_process() has to cope with that:

     - an empty PING must be answered with an empty PONG and consumed;
     - an empty PONG must be consumed and not surfaced to the application;
     - an empty CLOSE must reach the status callback and return
       NX_WEBSOCKET_DISCONNECTED;
     - an empty data frame must be consumed without being handed over, since
       there is no packet to hand over.

   Each frame is sent in its own TCP segment so that it arrives alone and the
   NX_NULL case is actually exercised.  The test also checks the client mutex is
   released on every path and that the packet pool is intact at the end.  */

#include    "tx_api.h"
#include    "nx_api.h"

