void thread_client_entry(ULONG thread_input)
{
UINT            i, status;
NX_PACKET      *packet_ptr;
NXD_ADDRESS     server_ip_address;
UINT            code;

    NX_PARAMETER_NOT_USED(thread_input);

    /* Create client socket.  */
    status = nx_tcp_socket_create(&client_ip, &test_client, "Client Socket", NX_IP_NORMAL, NX_FRAGMENT_OKAY,
                                  NX_IP_TIME_TO_LIVE, 1000, NX_NULL, NX_NULL);
    if (status)
        SET_ERROR_COUNTER(&error_counter, __FILE__, __LINE__);

    /* Create WebSocket.  */
    status = nx_websocket_client_create(&client_websocket, (UCHAR *)" ", &client_ip, &client_pool);
    if (status)
        SET_ERROR_COUNTER(&error_counter, __FILE__, __LINE__);

    /* Register the connection status callback so the CLOSE notification can be observed.  */
    status = nx_websocket_client_connection_status_callback_set(&client_websocket, NX_NULL, connection_status_callback);
    if (status)
        SET_ERROR_COUNTER(&error_counter, __FILE__, __LINE__);

    /* Give IP task and driver a chance to initialize the system.  */
    tx_thread_sleep(NX_IP_PERIODIC_RATE);

    status = nx_tcp_client_socket_bind(&test_client, TEST_SERVER_PORT, NX_IP_PERIODIC_RATE);
    if (status)
        SET_ERROR_COUNTER(&error_counter, __FILE__, __LINE__);

    while (!test_server_start)
    {
        tx_thread_sleep(NX_IP_PERIODIC_RATE);
    }

    server_ip_address.nxd_ip_address.v4 = TEST_SERVER_ADDRESS;
    server_ip_address.nxd_ip_version = NX_IP_VERSION_V4;

    status = nxd_tcp_client_socket_connect(&test_client, &server_ip_address, TEST_SERVER_PORT, NX_WAIT_FOREVER);
    if (status)
        SET_ERROR_COUNTER(&error_counter, __FILE__, __LINE__);

    /* Upgrade to websocket */
    status = nx_websocket_client_connect(&client_websocket, &test_client,
                                         TEST_HOST_NAME, sizeof(TEST_HOST_NAME) - 1,
                                         (UCHAR *)TEST_URI_PATH, sizeof(TEST_URI_PATH) - 1,
                                         (UCHAR *)TEST_PROTOCOL, sizeof(TEST_PROTOCOL) - 1,
                                         (UCHAR *)TEST_BEARER, sizeof(TEST_BEARER) - 1,
                                         NX_WAIT_FOREVER);
    if (status)
    {
        SET_ERROR_COUNTER(&error_counter, __FILE__, __LINE__);
        test_client_stop = 1;
        return;
    }

    /* Drain the connection.  A single receive call may consume several frames, so the
       frames are not matched one-to-one with calls: what matters is that no empty frame is
       ever handed to the application as data, that the mutex is released on every path, and
       that the peer's CLOSE is eventually reported.  */
    for (i = 0; i < 12; i++)
    {
        status = nx_websocket_client_receive(&client_websocket, &packet_ptr, &code, 2 * NX_IP_PERIODIC_RATE);

        /* Whatever happened, the mutex must not be left held.  */
        if (client_websocket.nx_websocket_client_mutex.tx_mutex_ownership_count != 0)
            SET_ERROR_COUNTER(&error_counter, __FILE__, __LINE__);

        if (status == NX_WEBSOCKET_DISCONNECTED)
        {

            /* The empty CLOSE was reported.  */
            close_reported = NX_TRUE;
            break;
        }
        else if (status == NX_SUCCESS)
        {

            /* None of the frames in this test carries a payload, so nothing should ever be
               handed over as application data.  */
            SET_ERROR_COUNTER(&error_counter, __FILE__, __LINE__);
            nx_packet_release(packet_ptr);
        }
        else if (status != NX_NO_PACKET)
        {

            /* NX_NO_PACKET simply means nothing was ready yet; anything else is a failure.  */
            SET_ERROR_COUNTER(&error_counter, __FILE__, __LINE__);
        }
    }

    if (close_reported != NX_TRUE)
        SET_ERROR_COUNTER(&error_counter, __FILE__, __LINE__);

    if (disconnect_callback_called != NX_TRUE)
        SET_ERROR_COUNTER(&error_counter, __FILE__, __LINE__);

    /* No packet may have been released twice or leaked along the way.  */
    if (client_pool.nx_packet_pool_invalid_releases)
        SET_ERROR_COUNTER(&error_counter, __FILE__, __LINE__);

    test_client_stop = 1;
}


/* Sends one frame in its own TCP segment.  */
static void send_frame(UCHAR *frame, ULONG frame_size)
{
UINT        status;
NX_PACKET  *packet_ptr;

    status = nx_packet_allocate(&server_pool, &packet_ptr, NX_TCP_PACKET, NX_IP_PERIODIC_RATE);
    if (status)
    {
        SET_ERROR_COUNTER(&error_counter, __FILE__, __LINE__);
        return;
    }

    status = nx_packet_data_append(packet_ptr, frame, frame_size, &server_pool, NX_IP_PERIODIC_RATE);
    if (status)
    {
        SET_ERROR_COUNTER(&error_counter, __FILE__, __LINE__);
        nx_packet_release(packet_ptr);
        return;
    }

    status = nx_tcp_socket_send(&test_server, packet_ptr, NX_IP_PERIODIC_RATE);
    if (status)
    {
        SET_ERROR_COUNTER(&error_counter, __FILE__, __LINE__);
        nx_packet_release(packet_ptr);
    }
}

void    thread_server_entry(ULONG thread_input)
{
UINT            status;
NX_PACKET      *packet_ptr;
UCHAR           opcode;

    NX_PARAMETER_NOT_USED(thread_input);

    printf("NetX Test:   Websocket Empty Control Frame Test........................");

    if (error_counter)
    {
        printf("ERROR!\n");
        test_control_return(1);
    }

    tx_thread_sleep(NX_IP_PERIODIC_RATE);

    status = nx_tcp_socket_create(&server_ip, &test_server, "Test Server Socket",
                                  NX_IP_NORMAL, NX_FRAGMENT_OKAY, NX_IP_TIME_TO_LIVE, 1000,
                                  NX_NULL, NX_NULL);
    if (status)
        SET_ERROR_COUNTER(&error_counter, __FILE__, __LINE__);

    status = nx_tcp_server_socket_listen(&server_ip, TEST_SERVER_PORT, &test_server, 5, NX_NULL);
    if (status)
        SET_ERROR_COUNTER(&error_counter, __FILE__, __LINE__);

    test_server_start = 1;

    status = nx_tcp_server_socket_accept(&test_server, 5 * NX_IP_PERIODIC_RATE);
    if (status)
        SET_ERROR_COUNTER(&error_counter, __FILE__, __LINE__);

    /* Complete the WebSocket handshake.  */
    status = nx_tcp_socket_receive(&test_server, &packet_ptr, 5 * NX_IP_PERIODIC_RATE);
    if (status)
        SET_ERROR_COUNTER(&error_counter, __FILE__, __LINE__);
    else
    {
        _server_connect_response_process(packet_ptr);
        memcpy(&server_switch_101[127], connect_key, 28); /* Use case of memcpy is verified. */

        packet_ptr -> nx_packet_append_ptr = packet_ptr -> nx_packet_prepend_ptr;
        packet_ptr -> nx_packet_length = 0;
        nx_packet_data_append(packet_ptr, server_switch_101, sizeof(server_switch_101), &server_pool, NX_IP_PERIODIC_RATE);
        status = nx_tcp_socket_send(&test_server, packet_ptr, NX_IP_PERIODIC_RATE);
        if (status)
        {
            SET_ERROR_COUNTER(&error_counter, __FILE__, __LINE__);
            nx_packet_release(packet_ptr);
        }
    }

    /* 1. An empty PING.  The client must answer with an empty PONG.  */
    send_frame(server_empty_ping, sizeof(server_empty_ping));

    status = nx_tcp_socket_receive(&test_server, &packet_ptr, 5 * NX_IP_PERIODIC_RATE);
    if (status)
        SET_ERROR_COUNTER(&error_counter, __FILE__, __LINE__);
    else
    {

        /* A client frame is masked, so only the low nibble of the first byte is the opcode.  */
        opcode = (UCHAR)(*(packet_ptr -> nx_packet_prepend_ptr) & 0x0F);
        if (opcode == NX_WEBSOCKET_OPCODE_PONG)
        {
            pong_seen = NX_TRUE;
        }
        else
        {
            SET_ERROR_COUNTER(&error_counter, __FILE__, __LINE__);
        }

        /* The echoed payload must be empty, so the frame is header plus mask only.  */
        if (packet_ptr -> nx_packet_length != 6)
            SET_ERROR_COUNTER(&error_counter, __FILE__, __LINE__);

        nx_packet_release(packet_ptr);
    }

    /* 2, 3 and 4: an empty PONG, an empty data frame and an empty CLOSE, each alone.  */
    tx_thread_sleep(NX_IP_PERIODIC_RATE);
    send_frame(server_empty_pong, sizeof(server_empty_pong));

    tx_thread_sleep(NX_IP_PERIODIC_RATE);
    send_frame(server_empty_text, sizeof(server_empty_text));

    tx_thread_sleep(NX_IP_PERIODIC_RATE);
    send_frame(server_empty_close, sizeof(server_empty_close));

    /* Wait for the client to finish its checks.  */
    while (!test_client_stop)
    {
        tx_thread_sleep(NX_IP_PERIODIC_RATE);
    }

    if (pong_seen != NX_TRUE)
        SET_ERROR_COUNTER(&error_counter, __FILE__, __LINE__);

    if (error_counter)
    {
        printf("ERROR!\n");
        test_control_return(1);
    }
    else
    {
        printf("SUCCESS!\n");
        test_control_return(0);
    }
}

